#include "bundle.h"
#include "paths.h"
#include "../core/log.h"
#include <windows.h>
#include <filesystem>
#include <cstdint>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <string_view>

namespace fs = std::filesystem;

namespace h7 {

// Resource layout (generated by build.bat into build\bundle.rc):
//   RCDATA 1000      manifest, one line per file: "<id> <keep|sync> <path relative to the engine root>"
//   RCDATA <id>      file contents
static constexpr int kManifestId = 1000;

static std::string_view LoadRc(HMODULE mod, int id) {
    HRSRC r = FindResourceW(mod, MAKEINTRESOURCEW(id), MAKEINTRESOURCEW(10) /* RT_RCDATA */);
    if (!r) return {};
    HGLOBAL g = LoadResource(mod, r);
    const void* p = g ? LockResource(g) : nullptr;
    return p ? std::string_view(static_cast<const char*>(p), SizeofResource(mod, r)) : std::string_view{};
}

static uint64_t Fnv1a(std::string_view data) {
    uint64_t h = 1469598103934665603ull;
    for (unsigned char c : data) h = (h ^ c) * 1099511628211ull;
    return h;
}

// data\bundled.txt: "<hash> <path>" of the bundled version last written for each sync file. A sync file is
// rewritten only when the DLL carries a different version than that, so edits to the installed copy survive
// restarts (development edits the game copy; see dist/CLAUDE.md) until the next DLL that changes the file.
static std::map<std::string, uint64_t> LoadInstalled(const fs::path& path) {
    std::map<std::string, uint64_t> m;
    std::ifstream in(path);
    uint64_t h;
    std::string rel;
    while (in >> std::hex >> h && std::getline(in >> std::ws, rel)) m[rel] = h;
    return m;
}

void InstallBundledFiles() {
    HMODULE self = nullptr;
    GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                       reinterpret_cast<LPCWSTR>(&InstallBundledFiles), &self);
    std::string_view manifest = LoadRc(self, kManifestId);
    if (manifest.empty()) {
        Log("No bundled files in this build");
        return;
    }
    fs::path statePath = fs::path(EnginePath(L"data")) / "bundled.txt";
    auto installed = LoadInstalled(statePath);
    bool stateChanged = false;
    int written = 0, total = 0;
    std::istringstream lines{std::string(manifest)};
    for (std::string line; std::getline(lines, line);) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        std::istringstream fields(line);
        int id = 0;
        std::string mode, rel;
        if (!(fields >> id >> mode) || !std::getline(fields >> std::ws, rel) || rel.empty()) continue;
        ++total;
        std::string_view data = LoadRc(self, id);
        fs::path path = fs::path(EngineRoot()) / Widen(rel);
        std::error_code ec;
        bool exists = fs::exists(path, ec);
        uint64_t hash = Fnv1a(data);
        if (mode == "keep" ? exists : (exists && installed.count(rel) && installed[rel] == hash)) continue;
        fs::create_directories(path.parent_path(), ec);
        std::ofstream out(path, std::ios::binary | std::ios::trunc);
        out.write(data.data(), (std::streamsize)data.size());
        if (!out) {
            Log("Could not write bundled file %s", rel.c_str());
            continue;
        }
        ++written;
        Log("Installed bundled file %s", rel.c_str());
        if (mode != "keep") installed[rel] = hash, stateChanged = true;
    }
    if (stateChanged) {
        std::error_code ec;
        fs::create_directories(statePath.parent_path(), ec);
        std::ofstream out(statePath, std::ios::trunc);
        for (auto& [rel, h] : installed) out << std::hex << h << ' ' << rel << '\n';
    }
    Log("Bundled files: %d of %d written", written, total);
}

} // namespace h7
